import React from "react";
import { BrowserRouter as Router, Route, Routes, Link } from "react-router-dom"; // Update: Use Routes instead of Switch
import goStemLogo from './components/GoStemLogo.png';
import './styles/App.css';

import LandingPage from "./landing-page";
import NotePage from "./note-page";
import ChatPage from "./chats-page";
import HoursPage from "./hours-page";
import ProfilePage from "./profile-page";
import SchedulePage from "./schedule-page";
import AdminSchedulePage from "./admin/admin-schedule-page";

function App() {
  return (
    <Router>
      <Routes> {/* Update: Use Routes instead of Switch */}
        <Route path="/" element={<Home />} /> {/* Update: Use element prop and JSX */}
        <Route path="/landing-page" element={<LandingPage />} />
        <Route path="/note-page" element={<NotePage />} />
        <Route path="/chats-page" element={<ChatPage />} />
        <Route path="/hours-page" element={<HoursPage />} />
        <Route path="/profile-page" element={<ProfilePage />} />
        <Route path="/schedule-page" element={<SchedulePage />} />
        <Route path="/admin-schedule-page" element={<AdminSchedulePage />} />
      </Routes>
    </Router>
  );
}

const Home = () => {
  return (
    <div className="App">
      <header className="Landing-page">
        <img src={goStemLogo} className="App-logo" alt="logo" />
        <a href="/accounts/google/login/?process=login">
          <button className="Login-button">
            Login
          </button>
        </a>
      </header>
    </div>
  );
};

export default App;
